import test from 'node:test';
import assert from 'node:assert/strict';
import {createRequire} from 'node:module';
import {fileURLToPath} from 'node:url';
import * as base from '../dist/ea-sim.mjs';
import {migrateState,hydrateState,cloneState} from '../dist/ea-state-v6.mjs';
import {initSpatial,validateSpatial,handlers,tickSpatial,placementIssue,spatialAccess,spatialPrefab,spatialTransform,spatialSlots,spatialFootprint,spatialProject,spatialUnproject,meterCanStand,meterFindPath,meterSweep,viewSpatial,polygonContains,SPATIAL_VERSION,SPATIAL_SCENE} from '../dist/ea-sr-spatial.mjs';
import {buildingAccess,scenicCanStand,scenicFindPath,buildingVisual} from '../dist/ea-scene-geometry.mjs';
import {interiorSlots,indoorRoofOpen} from '../dist/ea-hall-interior.mjs';
const fixture=()=>{const s=migrateState(base.initial(),{newGame:true});initSpatial(s);s.master.wound=0;s.master.energy=100;s.speed=1;for(const k of Object.keys(s.resources))s.resources[k]=10000;return s;};
function advance(s,n=1000){for(let i=0;i<n;i++){s.worldTick++;tickSpatial(s);}hydrateState(s);}
function advanceUntil(s,predicate,max=1200){for(let i=0;i<max&&!predicate();i++)advance(s,1);assert.ok(predicate(),`condition did not become true within ${max} ticks`);}
const atSite=s=>{const a=s.activitiesById[s.master.activityId];Object.assign(s.master.scenic,a.target,{path:[],goal:null});a.phase='working';};
function materialsAtSite(s){for(let i=0;i<1200&&s.workOrdersById[s.activitiesById[s.master.activityId]?.workOrderId]?.materialFlow?.phase!=='ready';i++){s.worldTick++;tickSpatial(s);}const o=s.workOrdersById[s.activitiesById[s.master.activityId]?.workOrderId];assert.equal(o?.materialFlow?.phase,'ready','reserved materials physically reached this worksite');assert.equal(o.progressTicks,0,'carrying and delivery do not add construction progress');validateSpatial(s);}
const finish=s=>{advance(s);assert.equal(s.master.activityId,null);validateSpatial(s);};
function screenEvent(renderer,canvas,p){const q=renderer.projectPoint(p),rect=canvas.getBoundingClientRect();return{clientX:q.x+(rect.left||0),clientY:q.y+(rect.top||0)};}
function addBuilding(s,type,x,y,level=1){const id=s.nextId++,b={id,instanceId:`building:yunxiu:${id}`,type,x,y,level,transform:{x,y,orientation:'south'},prefabId:`prefab:${type}:metres:v1`,sceneId:'scene:yunxiu-courtyard',condition:100,enabled:true,progress:0};s.buildings.push(b);return b;}

test('SR-XF-003-AC-01 / PATH-01: half-metre graph traverses a physical doorway and cannot cross wall or narrow gap',()=>{
 const s=fixture(),b=s.buildings[0],d=spatialPrefab(b),t=b.transform,entry=spatialAccess(b),inside={x:t.x+d.width/2,y:t.y+2};assert.ok(meterCanStand(s,inside));const path=meterFindPath(s,entry,inside,{maxSnap:0});assert.ok(path);let p=entry;for(const q of path){assert.equal(meterSweep(s,p,q).blocked,false);p=q;}assert.equal(meterCanStand(s,{x:t.x+.1,y:t.y+2}),false);assert.equal(meterSweep(s,{x:t.x-1,y:t.y+2},inside).blocked,true);
 const a=addBuilding(s,'library',8,15),z=addBuilding(s,'library',14.4,15);assert.equal(meterCanStand(s,{x:14.2,y:17}),false);const route=meterFindPath(s,{x:6,y:18},{x:22,y:18},{maxSnap:0});assert.ok(route);assert.ok(route.some(p=>p.y>=20||p.y<=15));
});
test('SR-XF-003-AC-02: near/overview/pointer projection has one inverse and keeps same selected point',()=>{for(const c of [{scale:32,depth:.65,ox:-500,oy:14},{scale:9,depth:.65,ox:28,oy:33},{scale:80,depth:.65,ox:120,oy:-82},{scale:32,depth:.65,ox:320,oy:240,rotation:Math.PI/4}])for(const p of [{x:27,y:9.6},{x:12.5,y:25},{x:0,y:0}]){const q=spatialUnproject(spatialProject(p,c),c);assert.ok(Math.abs(q.x-p.x)<1e-10&&Math.abs(q.y-p.y)<1e-10);}assert.equal(32*1.8,57.6);});
test('SR-XF-003-AC-02: selected exterior clears the measured portrait detail without moving world facts',async()=>{
 const {createWorldRenderer}=await import('../dist/ea-courtyard-renderer.mjs'),{estateSpriteBounds}=await import('../dist/ea-estate-assets.mjs');
 const s=fixture(),b=s.buildings[0],saved=structuredClone(s),ctx=new Proxy({measureText:t=>({width:t.length*7}),createLinearGradient:()=>({addColorStop(){}}),createRadialGradient:()=>({addColorStop(){}})},{get:(o,k)=>k in o?o[k]:()=>{},set:(o,k,v)=>(o[k]=v,true)});
 const canvas={width:820,height:1180,clientWidth:820,clientHeight:1180,getContext:()=>ctx,getBoundingClientRect:()=>({left:0,top:0,width:820,height:1180})},OldImage=globalThis.Image;
 globalThis.Image=class{width=1774;height=887;set src(v){queueMicrotask(()=>this.onload?.());}};
 try{
  let selection={kind:'building',id:b.id};const renderer=createWorldRenderer(canvas,{getState:()=>s,getMode:()=> 'inspect',getSelection:()=>selection,getCampaignScene:()=>null});await renderer.ready;renderer.focus(0,0);
  const bounds=()=>{const box=estateSpriteBounds(b,renderer.getCamera(),{project:spatialProject,prefab:spatialPrefab,transform:spatialTransform,visualStage:'complete'});return{left:box.x,top:box.y,right:box.x+box.width,bottom:box.y+box.height};};
  const overlap=(a,d)=>Math.max(0,Math.min(a.right,d.right)-Math.max(a.left,d.left))*Math.max(0,Math.min(a.bottom,d.bottom)-Math.max(a.top,d.top));
  const before=bounds(),left=Math.max(480,before.right-60),top=Math.max(100,before.top+5),panelRect={left,top,right:left+270,bottom:top+400,width:270,height:400},dock={dataset:{}},panel={parentElement:dock,getBoundingClientRect:()=>dock.dataset.detailDock==='bottom-right'?{left:520,top:830,right:790,bottom:1090,width:270,height:260}:panelRect};
  assert.ok(overlap(before,panelRect)>0,'the selected roof starts beneath the actual-size detail panel');
  assert.equal(renderer.keepSelectedBuildingVisible(panel),true);const clear=bounds();assert.equal(overlap(clear,panelRect),0,'the complete exterior clears the panel');assert.ok(clear.left>=8&&clear.right<=812&&clear.top>=8&&clear.bottom<=1172);
  assert.equal(renderer.keepSelectedBuildingVisible(panel),false,'an already clear selection does not drift');assert.deepEqual(bounds(),clear);
  const finger={clientX:350,clientY:500},held=renderer.screenPoint(finger);renderer.setZoom(.14,finger);const zoomed=renderer.screenPoint(finger);assert.ok(Math.hypot(held.x-zoomed.x,held.y-zoomed.y)<1e-9,'explicit touch point stays fixed even at the terrain clamp');
  const enlarged=bounds();Object.assign(panelRect,{left:enlarged.right-25,top:enlarged.top+5,right:enlarged.right+245,bottom:enlarged.top+405});assert.ok(overlap(enlarged,panelRect)>0);
  assert.equal(renderer.keepSelectedBuildingVisible(panel,{preserveAnchor:true}),true);assert.equal(dock.dataset.detailDock,'bottom-right');assert.equal(overlap(bounds(),panel.getBoundingClientRect()),0,'the detail moves clear of the enlarged exterior');const afterDock=renderer.screenPoint(finger);assert.ok(Math.hypot(held.x-afterDock.x,held.y-afterDock.y)<1e-9,'detail avoidance cannot move the touch point');
  for(let i=0;i<24;i++){const point=renderer.screenPoint(finger);renderer.setZoom(.14,finger);renderer.keepSelectedBuildingVisible(panel,{preserveAnchor:true});const box=bounds(),c=renderer.getCamera();assert.ok(box.left>=8-1e-4&&box.right<=c.w-8+1e-4&&box.top>=8-1e-4&&box.bottom<=c.h-8+1e-4,'continuous touch zoom keeps the complete exterior in the viewport');assert.ok(Math.hypot(point.x-renderer.screenPoint(finger).x,point.y-renderer.screenPoint(finger).y)<1e-9,'continuous zoom keeps the touched world point');assert.equal(overlap(box,panel.getBoundingClientRect()),0,'the detail remains clear through zoom');}
  selection=null;for(const finger of [{clientX:25,clientY:1150},{clientX:25,clientY:50}]){renderer.recenter();for(let i=0;i<20;i++){const point=renderer.screenPoint(finger);renderer.setZoom(-.14,finger);const c=renderer.getCamera(),si=Math.sin(c.rotation),co=Math.cos(c.rotation),left=c.ox-SPATIAL_SCENE.height*si*c.scale,right=c.ox+SPATIAL_SCENE.width*co*c.scale,top=c.oy,bottom=c.oy+(SPATIAL_SCENE.width*si+SPATIAL_SCENE.height*co)*c.scale*c.depth,visibleRight=c.w;if(right-left>=visibleRight)assert.ok(left<=1e-3&&right>=visibleRight-1e-3,'landscape covers horizontal view');else assert.ok(Math.abs(left+right-visibleRight)<1e-3,'small landscape stays horizontally centered');if(bottom-top>=c.h)assert.ok(top<=1e-3&&bottom>=c.h-1e-3,'landscape covers vertical view');else assert.ok(Math.abs(top+bottom-c.h)<1e-3,'small landscape stays vertically centered');assert.ok(Math.hypot(point.x-renderer.screenPoint(finger).x,point.y-renderer.screenPoint(finger).y)<1e-9,'edge touch point remains stable');}}
  selection={kind:'building',id:b.id};renderer.focus(0,0);
  renderer.setOverview(true);renderer.setZoom(.14);renderer.keepSelectedBuildingVisible(panel);const entry=spatialAccess(b),projected=renderer.projectPoint(entry),inverse=renderer.screenPoint({clientX:projected.x,clientY:projected.y});assert.ok(Math.hypot(inverse.x-entry.x,inverse.y-entry.y)<1e-9,'overview return keeps the same world entrance');
  assert.deepEqual(structuredClone(s),saved,'detail avoidance changes camera only');renderer.destroy();
 }finally{globalThis.Image=OldImage;}
});
test('SR-XF-003-AC-03 / SAVE-01: deterministic legacy map, geometry repair and no clock/assets/identity changes',()=>{const old=migrateState(base.initial({seed:45}),{newGame:true}),before={tick:old.worldTick,resources:structuredClone(old.resources),ids:Object.keys(old.personsById),story:structuredClone(old.story)};const a=cloneState(old),b=cloneState(old);initSpatial(a);initSpatial(b);assert.deepEqual(a.spatial,b.spatial);assert.deepEqual(a.buildings.map(b=>b.transform),b.buildings.map(b=>b.transform));assert.equal(a.worldTick,before.tick);assert.deepEqual(a.resources,before.resources);assert.deepEqual(Object.keys(a.personsById),before.ids);assert.deepEqual(a.story,before.story);const saved=structuredClone(a);initSpatial(a);assert.deepEqual(structuredClone(a),saved);assert.equal(a.master.scenic.geometry,SPATIAL_VERSION);validateSpatial(a);});
test('SR-XF-004-AC-01: all 14 prefabs share preview/site/final footprint and visible furniture matches capacity',()=>{const s=fixture();for(const type of Object.keys(base.BUILDINGS))for(let level=1;level<=3;level++){const b={id:99,instanceId:'building:yunxiu:99',type,level,transform:{x:35,y:35,orientation:'south'}},d=spatialPrefab(b),v=buildingVisual(b);assert.deepEqual(v.footprint,spatialFootprint(b));assert.deepEqual(spatialAccess(b),buildingAccess(s,b));if(base.BUILDINGS[type].capacity){assert.equal(d.furniture.filter(f=>f.kind==='bed').length,base.BUILDINGS[type].capacity*level);assert.equal(spatialSlots(b,'rest').length,base.BUILDINGS[type].capacity*level);}assert.deepEqual(d.orientations,['south']);}});
test('SR-XF-004-AC-02: sleep/study/heal slots stay real behind the closed roof and door is not a workstation',()=>{const s=fixture(),b=s.buildings[0],d=spatialPrefab(b);for(const kind of ['rest','study','heal'])for(const slot of interiorSlots(s,b,kind)){assert.ok(meterCanStand(s,slot.position),slot.id);assert.notDeepEqual(slot.position,spatialAccess(b));assert.ok(meterFindPath(s,spatialAccess(b),slot.position),slot.id);assert.equal(indoorRoofOpen(s,b,{actors:[slot.position]}),false);}});
test('SR-XF-004-AC-03: transparent vector fallback keeps instance and supported orientation, capacity defined by actual prefab',()=>{const s=fixture(),b=addBuilding(s,'house',35,35),id=b.instanceId,view=buildingVisual(b);assert.equal(view.prefab.fallback,'same-style-vector');assert.equal(b.instanceId,id);assert.equal(spatialSlots(b,'rest').length,4);assert.equal(view.prefab.assetVersion,'vector-metres-v1');});
test('SR-XF-005-AC-01 / BUILD-03: arbitrary half-metre location, only arrived worker contributes and capacity starts at completion',()=>{const s=fixture(),result=handlers.build(s,'house',12.5,24.5),o=s.workOrdersById[result.workOrderId];assert.equal(s.buildings.some(b=>b.id===result.id),false);tickSpatial(s);assert.equal(o.progressTicks,0);materialsAtSite(s);advanceUntil(s,()=>o.progressTicks>0);assert.equal(o.progressTicks,1);assert.ok(o.workSlots.some(slot=>slot.occupantId==='person:master'&&Math.hypot(s.master.scenic.x-slot.position.x,s.master.scenic.y-slot.position.y)<.1));assert.equal(viewSpatial(s).stage,'foundation');advanceUntil(s,()=>o.progressTicks>=o.durationTicks/3);assert.equal(viewSpatial(s).stage,'structure');advanceUntil(s,()=>o.progressTicks>=o.durationTicks*2/3);assert.equal(viewSpatial(s).stage,'finishing');finish(s);const b=s.buildings.find(b=>b.id===result.id);assert.deepEqual(b.transform,{x:12.5,y:24.5,orientation:'south'});assert.equal(spatialSlots(b,'rest').length,4);});
test('SR-XF-005-AC-02 / BUILD-02: named person, protected/water terrain and blocked entry reject atomically',()=>{const s=fixture();Object.assign(s.master.scenic,{x:12.5,y:24.5,path:[]});const resources=structuredClone(s.resources),position=structuredClone(s.master.scenic),next=s.nextId;assert.throws(()=>handlers.build(s,'farm',12,24),/正在此处/);assert.deepEqual(s.resources,resources);assert.deepEqual(s.master.scenic,position);assert.equal(s.nextId,next);assert.match(placementIssue(s,'farm',58,10),/水面|边界/);assert.match(placementIssue(s,'farm',30,57),/入口保护区|边界/);const hall=s.buildings[0],entry=spatialAccess(hall);assert.match(placementIssue(s,'farm',Math.floor(entry.x),Math.floor(entry.y)),/入口/);});
test('SR-XF-005-AC-03 / BUILD-01: confirm/cancel/pause/reload preserves one reservation and refunds only unspent materials once',()=>{const s=fixture(),before=structuredClone(s.resources),r=handlers.build(s,'farm',12.5,24.5),o=s.workOrdersById[r.workOrderId];assert.throws(()=>handlers.build(s,'farm',22,24),/当前营造/);materialsAtSite(s);advanceUntil(s,()=>o.progressTicks>=40);const usedWood=Math.floor(25*o.progressTicks/o.durationTicks);s.speed=0;const held=structuredClone(s);tickSpatial(s);assert.deepEqual(structuredClone(s),held);const reload=cloneState(s);validateSpatial(reload);const out=handlers.cancelConstruction(reload);assert.equal(out.usedCost.wood,usedWood);assert.equal(out.pending,true,'site materials need an actual return trip');assert.equal(reload.resources.wood,before.wood-25,'onsite remainder has not reached the warehouse');reload.speed=1;advance(reload,1000);assert.equal(reload.resources.wood,before.wood-usedWood);assert.equal(reload.spatial.completedOrders.filter(o=>o.id===r.workOrderId&&o.phase==='cancelled').length,1);const after=structuredClone(reload.resources);handlers.cancelConstruction(reload);assert.deepEqual(reload.resources,after);assert.equal(Object.keys(reload.reservationsById).length,0);});
test('SR-XF-006-AC-01 / BUILD-04: occupied bed safely exits on a real route before relocation and keeps identity',()=>{const s=fixture(),b=addBuilding(s,'house',12,24),p=base.addDisciple(s,{name:'占床门人'}),slot=spatialSlots(b,'rest')[0];p.mind.scenic={...slot.position,path:[],steps:0,facing:1,back:false};p.activityId='activity:sleeper';s.activitiesById[p.activityId]={id:p.activityId,kind:'facility',action:'rest',targetId:b.instanceId,reservationId:'reservation:sleeper',personId:p.personId,phase:'executing',slotId:slot.id};s.reservationsById['reservation:sleeper']={id:'reservation:sleeper',kind:'slot',personId:p.personId,slotId:slot.id,activityId:p.activityId};const result=handlers.relocate(s,b.id,35.5,35.5);materialsAtSite(s);tickSpatial(s);assert.deepEqual(b.transform,{x:12,y:24,orientation:'south'});assert.equal(s.activitiesById[s.master.activityId].phase,'blocked');finish(s);assert.equal(b.instanceId,result.id&&`building:yunxiu:${result.id}`);assert.deepEqual(b.transform,{x:35.5,y:35.5,orientation:'south'});assert.equal(meterCanStand(s,p.mind.scenic),true);assert.equal(s.spatial.completedOrders.at(-1).evacuations.length,1);});
test('SR-XF-006-AC-02: target invalidation holds original, mid-task cancel/reload does not copy or duplicate refund',()=>{const s=fixture(),b=addBuilding(s,'farm',12,24),original={...b.transform};handlers.relocate(s,b.id,35.5,35.5);materialsAtSite(s);advance(s,30);const reload=cloneState(s),restored=reload.buildingsById[b.instanceId];assert.deepEqual(restored.transform,original);addBuilding(reload,'library',35.5,35.5);const mid=cloneState(reload);advance(reload,300);assert.deepEqual(restored.transform,original);assert.equal(reload.activitiesById[reload.master.activityId].phase,'blocked');const finished=handlers.cancelConstruction(reload);assert.equal(finished.refund.wood,0,'all construction material was consumed before final placement was blocked');const spent=structuredClone(reload.resources);handlers.cancelConstruction(reload);assert.deepEqual(reload.resources,spent);const pending=handlers.cancelConstruction(mid);assert.equal(pending.pending,true,'unused site material needs an actual return trip');advance(mid,1000);const cost=structuredClone(mid.resources);handlers.cancelConstruction(mid);assert.deepEqual(mid.resources,cost);assert.equal(mid.spatial.completedOrders.filter(o=>o.id===`work:construction:${b.id}`&&o.phase==='cancelled').length,1);assert.equal(mid.buildings.filter(v=>v.instanceId===b.instanceId).length,1);assert.deepEqual(mid.buildingsById[b.instanceId].transform,original);validateSpatial(mid);validateSpatial(reload);});
test('SR-XF-006-AC-03: occupied expanded footprint rejects completion; successful upgrade uses larger furniture and same buildingId',()=>{const s=fixture(),b=addBuilding(s,'house',12,24),block=addBuilding(s,'farm',18.5,24),resources=structuredClone(s.resources);assert.throws(()=>handlers.upgrade(s,b.id),/冲突/);assert.deepEqual(s.resources,resources);s.buildings=s.buildings.filter(v=>v.id!==block.id);const id=b.instanceId;handlers.upgrade(s,b.id);atSite(s);finish(s);assert.equal(b.instanceId,id);assert.equal(b.level,2);assert.equal(spatialPrefab(b).width,8);assert.equal(spatialSlots(b,'rest').length,8);});
