   canvas.clientWidth=w;canvas.clientHeight=h;globalThis.devicePixelRatio=dpr;renderer.resize();assert.equal(canvas.width,Math.round(w*Math.min(dpr,1.75)));assert.equal(canvas.height,Math.round(h*Math.min(dpr,1.75)));
