   if(right-left>=w)assert.ok(left<=1e-8&&right>=w-1e-8,'rotated scene bounds cover viewport width');else assert.ok(Math.abs(left-(w-right))<1e-8,'narrow rotated scene remains horizontally centered');
   if(bottom-top>=h)assert.ok(top<=1e-8&&bottom>=h-1e-8,`rotated scene bounds cover viewport height ${w}x${h}: ${top}..${bottom}`);else assert.ok(Math.abs(top-(h-bottom))<1e-8,'short rotated scene remains vertically centered');
